import Link from 'next/link'
import { useRouter } from 'next/router'
import { useState, useRef, useEffect } from 'react'

const items = [
  {href: '/', label: 'Home'},
  {href: '/dashboard', label: 'Dashboard'},
  {href: '/produtos', label: 'Produtos'},
  {href: '/clientes', label: 'Clientes'},
]

export default function Sidebar(){
  const router = useRouter()
  const [open, setOpen] = useState(false)
  const dropdownRef = useRef(null)

  useEffect(()=>{
    function onDocClick(e){
      if (!dropdownRef.current) return
      if (!dropdownRef.current.contains(e.target)) setOpen(false)
    }
    function onEsc(e){ if (e.key === 'Escape') setOpen(false) }
    document.addEventListener('click', onDocClick)
    document.addEventListener('keydown', onEsc)
    return ()=>{
      document.removeEventListener('click', onDocClick)
      document.removeEventListener('keydown', onEsc)
    }
  },[])

  return (
    <header className="sidebar top-nav">
      <div className="brand">eZion</div>

      <nav className="nav">
        {items.map(it=> (
          <Link key={it.label} href={it.href} className={`nav-item ${router.pathname === it.href ? 'active' : ''}`}>
            {it.label}
          </Link>
        ))}

        {/* Vendas dropdown */}
        <div ref={dropdownRef} className={`nav-item has-dropdown ${router.pathname.startsWith('/vendas') ? 'active' : ''} ${open? 'open':''}`}>
          <div className="nav-link-wrap">
            <Link href="/vendas" className="nav-link">Vendas</Link>
            <button
              aria-haspopup="true"
              aria-expanded={open}
              aria-controls="vendas-dropdown"
              className="dropdown-toggle"
              onClick={(e)=>{ e.stopPropagation(); setOpen(s=>!s) }}
              >
              ▾
            </button>
          </div>
          <div id="vendas-dropdown" className="dropdown-menu" role="menu">
            <Link href="/vendas/clientes" className={`dropdown-item ${router.pathname === '/vendas/clientes' ? 'active' : ''}`}>Clientes</Link>
            <Link href="/vendas/pedidos" className={`dropdown-item ${router.pathname === '/vendas/pedidos' ? 'active' : ''}`}>Pedidos</Link>
          </div>
        </div>
      </nav>

      <div className="top-nav-actions">
        <input className="search" placeholder="Pesquisar..." />
        <div className="user">
          <div className="avatar">EZ</div>
          <div className="user-info">
            <div className="user-name">Gildecio</div>
            <div className="user-role muted">Administrador</div>
          </div>
        </div>
      </div>
    </header>
  )
}
